import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"ODD","description":"","frontmatter":{},"headers":[],"relativePath":"agents/odd.md","filePath":"agents/odd.md"}'),o={name:"agents/odd.md"};function d(i,e,c,l,h,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="odd" tabindex="-1">ODD <a class="header-anchor" href="#odd" aria-label="Permalink to &quot;ODD&quot;">​</a></h1><p>A repository planned with ODD (Organic Driven Development, from <a href="https://github.com/Gentleman-Programming/gentle-ai" target="_blank" rel="noreferrer">Gentle AI</a>) keeps each feature in one document, <code>odd/tasks/&lt;feature&gt;.md</code>, with <code>## Specs</code>, <code>## Tasks</code> and <code>## Log</code>.</p><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><p>ODD needs nothing installed: create the <code>odd/tasks/</code> directory with a first feature document, or let your agent write it. <code>wake init</code> then finds a <code>.md</code> file in <code>odd/tasks/</code> and records ODD as the plan. When the repository also has OpenSpec, OpenSpec wins unless you run <code>wake init --plan odd</code>; with both <code>.specify/</code> and <code>odd/tasks/</code> (and no OpenSpec), choose with <code>wake init --plan spec-kit</code> or <code>wake init --plan odd</code>.</p><h2 id="planning-with-your-agent" tabindex="-1">Planning with your agent <a class="header-anchor" href="#planning-with-your-agent" aria-label="Permalink to &quot;Planning with your agent&quot;">​</a></h2><p>Ask your agent for a new feature, or run its plan command (such as <code>/wake:plan &lt;idea&gt;</code> in Claude Code). Its <code>wake-planning</code> skill plans the feature as a new document, <code>odd/tasks/&lt;feature&gt;.md</code>. Milestones live in <code>odd/milestones.yaml</code>, in the <a href="/wake-dist/docs/agents/milestones#group-changes-into-milestones">milestones format</a>, with document names under <code>changes</code>. <code>wake watch</code> syncs on every change under <code>odd/tasks/</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>odd/</span></span>
<span class="line"><span>  tasks/</span></span>
<span class="line"><span>    login.md        # ## Tasks: a table or checkbox lines</span></span>
<span class="line"><span>    billing.md</span></span>
<span class="line"><span>    search.md       # no ## Tasks yet: no phase, but milestones may name it</span></span>
<span class="line"><span>  milestones.yaml   # optional; changes: [login, billing]</span></span></code></pre></div><h2 id="how-wake-reads-documents-and-tasks" tabindex="-1">How Wake reads documents and tasks <a class="header-anchor" href="#how-wake-reads-documents-and-tasks" aria-label="Permalink to &quot;How Wake reads documents and tasks&quot;">​</a></h2><p>Each document directly in <code>odd/tasks/</code> with a <code>## Tasks</code> section is a phase (its file name without <code>.md</code>, lowercased), ordered by the commit that first added it. Only the lines between <code>## Tasks</code> and the next <code>##</code> heading are read, in either shape:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| ID | Task | Specs | Route | Status | Commit |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|----|------|-------|-------|--------|--------|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| T1 | Parse the table | S1 | inline | done, verified | 6c66491 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| T2 | Watch odd/tasks | S2 | inline | pending | |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] T3 (S2-S5) inline · Read checkbox lines · RED→GREEN · 6c664915</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**T-04 — Retire the old flag**</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Route: inline</span></span></code></pre></div><ul><li>A table needs an <code>ID</code> and a <code>Status</code> column. The title is the <code>Task</code> column, else <code>Change</code>, else the first column whose header contains <code>task</code> or <code>change</code> (such as <code>Phase / change</code>), else the column after <code>ID</code>. A row is done when its status&#39;s first word is <code>done</code>, <code>released</code>, <code>complete</code> or <code>completed</code> (<code>Done.</code> and <code>released (a8b3406)</code> count); anything else, such as <code>pending</code> or <code>approved by the user</code>, is open. <code>\\|</code> is a literal pipe. A table without a <code>Status</code> column gives no tasks.</li><li>A checkbox line starts with a task id (letters, an optional <code>-</code>, digits and optional letters: <code>T1</code>, <code>T8b</code>, <code>G2</code>, <code>T-01</code>). Its title drops a leading <code>(S…)</code> and is the first <code>·</code> segment that does not start with <code>inline</code> or <code>delegated</code>, or for a bold <code>**T-01 — Title**</code> the text after the dash. Indented lines describe it, and one starting with <code>Done when:</code> says how to tell it is finished; the task detail in the web app shows them as Includes and Done when. <code>[x]</code> or <code>[X]</code> marks it done.</li><li>A table row has no room for a description or a <code>Done when:</code> line, so its Includes and Done when stay empty; use checkbox lines for tasks that need them. <code>wake sync</code> and <code>wake doctor</code> point out open checkbox tasks without a <code>Done when:</code> line, never table rows.</li></ul><p>The task id is the task&#39;s number. A checkbox without a task id, a row with an empty <code>ID</code>, a task id used twice in one document and a document name that is no phase id are errors printed as <code>path:line: message</code>, and nothing is sent. Wake never writes into ODD documents: a task&#39;s id is derived from its document and its task id, so rewording a task or changing its status keeps its identity; a trailing <code>&lt;!-- wake:&lt;id&gt; --&gt;</code> marker (on a checkbox line or at the end of the title cell) wins.</p>`,12)])])}const u=a(o,[["render",d]]);export{k as __pageData,u as default};
